package com.howierux.mortalexpansion.data;
import com.howierux.mortalexpansion.catalog.*;import com.google.gson.*;import com.mojang.serialization.JsonOps;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.data.*;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.tags.TagKey;import net.fabricmc.fabric.api.datagen.v1.*;import net.fabricmc.fabric.api.recipe.v1.ingredient.DefaultCustomIngredients;import java.util.*;import java.util.concurrent.*;
/** NeoForge patches native diamond ingredients to shared tags. Fabric generates that contract through native recipe codecs. */
public final class VanillaDiamondRecipes implements DataProvider {
 private final FabricDataOutput output;private final CompletableFuture<HolderLookup.Provider> lookup;
 public VanillaDiamondRecipes(FabricDataOutput o,CompletableFuture<HolderLookup.Provider> l){output=o;lookup=l;}
 public String getName(){return "Diamond-equivalent vanilla recipes";}
 private static final Set<String> GEAR=Set.of("diamond_helmet","diamond_chestplate","diamond_leggings","diamond_boots","diamond_sword","diamond_pickaxe","diamond_axe","diamond_shovel","diamond_hoe");
 private static boolean replace(JsonElement node,JsonElement diamond){boolean changed=false;if(node.isJsonObject()){var obj=node.getAsJsonObject();if(obj.size()==1&&obj.has("item")&&obj.get("item").getAsString().equals("minecraft:diamond")){obj.remove("item");for(var e:diamond.getAsJsonObject().entrySet())obj.add(e.getKey(),e.getValue().deepCopy());return true;}for(var entry:new ArrayList<>(obj.entrySet()))changed|=replace(entry.getValue(),diamond);}else if(node.isJsonArray())for(var child:node.getAsJsonArray())changed|=replace(child,diamond);return changed;}
 public CompletableFuture<?> run(CachedOutput cache){return lookup.thenCompose(registries->{try{var tasks=new ArrayList<CompletableFuture<?>>();var paths=output.createPathProvider(PackOutput.Target.DATA_PACK,"recipe");var ops=RegistryOps.create(JsonOps.INSTANCE,registries);var tag=TagKey.create(Registries.ITEM,ResourceLocation.parse("c:gems/diamond"));var diamond=Ingredient.CODEC.encodeStart(ops,Ingredient.of(tag)).getOrThrow();var protectedDiamond=Ingredient.CODEC.encodeStart(ops,DefaultCustomIngredients.difference(Ingredient.of(tag),Ingredient.of(CatalogItems.BLOODSTONE))).getOrThrow();var location=java.nio.file.Path.of(Recipe.class.getProtectionDomain().getCodeSource().getLocation().toURI());try(var jar=new java.util.jar.JarFile(location.toFile())){var entries=jar.entries();while(entries.hasMoreElements()){var entry=entries.nextElement();String path=entry.getName();if(!path.startsWith("data/minecraft/recipe/")||!path.endsWith(".json"))continue;JsonObject recipe;try(var reader=new java.io.InputStreamReader(jar.getInputStream(entry),java.nio.charset.StandardCharsets.UTF_8)){recipe=JsonParser.parseReader(reader).getAsJsonObject();}String type=recipe.get("type").getAsString();if(!type.equals("minecraft:crafting_shaped")&&!type.equals("minecraft:crafting_shapeless"))continue;String name=path.substring("data/minecraft/recipe/".length(),path.length()-5);boolean changed=false;var ingredient=GEAR.contains(name)?protectedDiamond:diamond;for(String key:List.of("key","ingredients"))if(recipe.has(key))changed|=replace(recipe.get(key),ingredient);if(!changed)continue;if(GEAR.contains(name)&&recipe.has("key"))for(var e:recipe.getAsJsonObject("key").entrySet()){if(e.getValue().isJsonObject()){var o=e.getValue().getAsJsonObject();if(o.has("item")&&o.get("item").getAsString().equals("minecraft:stick")){o.remove("item");o.addProperty("tag","c:rods/wooden");}}}var parsed=Recipe.CODEC.parse(ops,recipe).getOrThrow();tasks.add(DataProvider.saveStable(cache,registries,Recipe.CODEC,parsed,paths.json(ResourceLocation.withDefaultNamespace(name))));}}return CompletableFuture.allOf(tasks.toArray(CompletableFuture[]::new));}catch(Exception error){throw new IllegalStateException("Could not generate native diamond-equivalent recipes",error);}});}
}
